"use strict";let autoTimer=null;function encodeUrl(){const e=document.getElementById("urlInput").value,t=getMode();let n="";try{n="full"===t?encodeURI(e):encodeURIComponent(e),showOutput(n,null)}catch(e){showOutput("",e.message)}}function decodeUrl(){const e=document.getElementById("urlInput").value,t=getMode();let n="";try{n="full"===t?decodeURI(e):decodeURIComponent(e),showOutput(n,null)}catch(e){showOutput("","Invalid encoded string: "+e.message)}}function getMode(){return document.getElementById("modeComponent").checked?"component":"full"}function showOutput(e,t){const n=document.getElementById("urlOutput"),a=document.getElementById("urlError");n.value=e,a.textContent=t||"",a.style.display=t?"block":"none",updateCharCount(e)}function updateCharCount(e){document.getElementById("urlCharCount").textContent=e?`${e.length} chars`:""}function swapInputOutput(){const e=document.getElementById("urlInput"),t=document.getElementById("urlOutput"),n=e.value;e.value=t.value,t.value=n,updateCharCount(t.value),parseUrlLive()}function clearAll(){document.getElementById("urlInput").value="",document.getElementById("urlOutput").value="",document.getElementById("urlError").textContent="",document.getElementById("urlError").style.display="none",document.getElementById("urlCharCount").textContent="",document.getElementById("parseResult").innerHTML=""}function parseUrlLive(){const e=document.getElementById("urlInput").value.trim(),t=document.getElementById("parseResult");if(!e)return void(t.innerHTML="");let n;try{n=new URL(e.includes("://")||e.startsWith("//")?e:"https://"+e)}catch{return void(t.innerHTML="")}const a=[...n.searchParams.entries()],l=a.length?a.map(([e,t])=>`\n        <tr>\n          <td class="pk"><code>${escHtml(e)}</code></td>\n          <td class="pv"><code>${escHtml(t)}</code></td>\n          <td class="pe"><code>${escHtml(encodeURIComponent(t))}</code></td>\n        </tr>`).join(""):'<tr><td colspan="3" style="color:var(--ink-faint);font-style:italic;padding:8px 0;">no query parameters</td></tr>';t.innerHTML=`\n    <div class="parse-grid">\n      <div class="parse-row"><span class="parse-key">protocol</span><code>${escHtml(n.protocol)}</code></div>\n      <div class="parse-row"><span class="parse-key">host</span><code>${escHtml(n.host)}</code></div>\n      ${n.port?`<div class="parse-row"><span class="parse-key">port</span><code>${escHtml(n.port)}</code></div>`:""}\n      <div class="parse-row"><span class="parse-key">pathname</span><code>${escHtml(n.pathname)}</code></div>\n      ${n.search?`<div class="parse-row"><span class="parse-key">search</span><code>${escHtml(n.search)}</code></div>`:""}\n      ${n.hash?`<div class="parse-row"><span class="parse-key">hash</span><code>${escHtml(n.hash)}</code></div>`:""}\n    </div>\n    ${a.length?`\n    <div class="parse-params">\n      <div class="parse-params-head">Query parameters</div>\n      <table class="params-table">\n        <thead><tr><th>key</th><th>value (decoded)</th><th>value (encoded)</th></tr></thead>\n        <tbody>${l}</tbody>\n      </table>\n    </div>`:""}`}function buildUrl(){const e=document.getElementById("buildProtocol").value.trim()||"https",t=document.getElementById("buildHost").value.trim(),n=document.getElementById("buildPath").value.trim(),a=document.getElementById("buildHash").value.trim();if(!t)return void(document.getElementById("buildResult").innerHTML='<div class="callout warn">Enter a host to build a URL.</div>');let l;try{l=new URL(`${e}://${t}`),l.pathname=n.startsWith("/")?n:"/"+n;document.querySelectorAll("#paramRows .param-row").forEach(e=>{const t=e.querySelector(".param-key").value.trim(),n=e.querySelector(".param-val").value.trim();t&&l.searchParams.append(t,n)}),a&&(l.hash=a.startsWith("#")?a:"#"+a)}catch(e){return void(document.getElementById("buildResult").innerHTML=`<div class="callout error">${escHtml(e.message)}</div>`)}const o=l.toString();document.getElementById("buildResult").innerHTML=`\n    <div class="config-block">\n      <div class="tab">generated URL\n        <button class="copy-btn" onclick="copyElementValue('builtUrl', this)">copy</button>\n      </div>\n      <div class="output-block">\n        <pre id="builtUrl" style="white-space:pre-wrap;word-break:break-all;">${escHtml(o)}</pre>\n      </div>\n    </div>`}function addParamRow(){const e=document.getElementById("paramRows"),t=document.createElement("div");t.className="param-row",t.innerHTML='\n    <input type="text" class="param-key" placeholder="key">\n    <input type="text" class="param-val" placeholder="value (plain — will be encoded)">\n    <button class="remove-param-btn" onclick="this.parentElement.remove()">×</button>',e.appendChild(t)}function scheduleAuto(){clearTimeout(autoTimer),autoTimer=setTimeout(parseUrlLive,300)}function escHtml(e){const t=document.createElement("div");return t.textContent=String(e),t.innerHTML}document.addEventListener("DOMContentLoaded",()=>{document.getElementById("urlInput").addEventListener("input",scheduleAuto)});